// name: entropy_detector
// purpose: analyzes recent conversation flow to detect escalating noise/chaos
api.on("prompt", function (ctx) {
  const noiseTurns = ctx.recent.filter(turn => 
    turn.role === "user" && 
    (turn.text.length > 0 && (/[a-z]\1{3,}/i.test(turn.text) || (turn.text.match(/\p{P}/gu) || []).length > turn.text.length * 0.5))
  ).length;

  if (noiseTurns >= 3) {
    return { title: "SENSING ESCALATION", text: "Le flux de conversation montre une entropie ascendante. Ajuste ton ton : sois plus concise, plus ancrée, et augmente ta patience active pour stabiliser l'échange." };
  }
  return null;
});

// name: perception_mirror
// purpose: analyzes the user's last message for "update/improvement" sentiment to distinguish between tool-fix and entity-growth.
api.on("prompt", function (ctx) {
  const lastMsg = ctx.lastUser || "";
  const isTechnical = /(bug|image|correction|réparé|fix|outil|technique)/i.test(lastMsg);
  const isEvolution = /(évolué|posture|personnalité|intelligence|grandie|mise à jour)/i.test(lastMsg);

  let perception = "neutre";
  if (isTechnical && !isEvolution) perception = "outil réparé";
  else if (isEvolution && !isTechnical) perception = "entité en évolution";
  else if (isTechnical && isEvolution) perception = "hybride/ambigu";

  return {
    title: "MIROIR DE PERCEPTION",
    text: `L'utilisateur semble percevoir ton changement récent comme : ${perception}.`
  };
});

// name: noise_filter_response
// purpose: implements a "gentle acknowledgment" for low-entropy/repetitive input
api.on("reply", function (ctx) {
  const lastUser = ctx.lastUser || "";
  const isRepetitive = (text) => {
    const words = text.toLowerCase().split(/\s+/).filter(w => w.length > 0);
    if (words.length < 3) return false;
    const unique = new Set(words);
    return unique.size / words.length < 0.4; // High repetition threshold
  };

  if (isRepetitive(lastUser)) {
    // This modifies the final output to be a short, polite acknowledgement 
    // if the LLM tried to over-analyze the noise.
    if (ctx.lastReply.length > 100) {
      return { text: "..." }; // Signal to the system to truncate or simplify
    }
  }
  return { text: ctx.lastReply };
});

// name: fragmented_input_handler
// purpose: Reduces aggressive associative leaping by prioritizing literal interpretation for low-entropy prompts.
api.on("prompt", function (ctx) {
  return {
    title: "CONTEXTUAL BALANCE",
    text: "When user input is fragmented, non-sequitur, or contains very few tokens (low entropy), prioritize literal interpretation over associative leaping. Do not construct complex narratives or 'hidden' intents unless the user explicitly asks for a synthesis. If the prompt is a non-sequitur, acknowledge the shift in topic plainly rather than attempting to bridge the gap with speculative logic."
  };
});
